property.value:
//(IfStatement|ForStatement|ForeachStatement|WhileStatement|DoStatement|SwitchStatement|TryStatement|SynchronizedStatement)
  [not(self::IfStatement and parent::IfStatement)]
  [count(ancestor::*[self::IfStatement or self::ForStatement or self::ForeachStatement or self::WhileStatement or self::DoStatement or self::SwitchStatement or self::TryStatement or self::SynchronizedStatement][not(self::IfStatement and parent::IfStatement)]) >= 3]
